javascript:(function(){if(window.__jz_inspector_active){var e=document.getElementById('__jz_inspector');if(e)e.remove();window.__jz_inspector_active=false;return;}window.__jz_inspector_active=true;var d=document.createElement('style');d.id='__jz_inspector_css';d.textContent="#__jz_inspector{all:initial;position:fixed;z-index:2147483647;right:12px;bottom:12px;width:420px;height:320px;box-shadow:0 10px 30px rgba(0,0,0,.6);border-radius:8px;overflow:hidden;font-family:system-ui,Segoe UI,Roboto,Helvetica,Arial,sans-serif;font-size:13px;color:#e6eef6}#__jz_inspector *{box-sizing:border-box}#__jz_header{display:flex;align-items:center;gap:8px;padding:8px;background:linear-gradient(180deg,#0b1220,#07101a);color:#9fb8ff}#__jz_header b{font-size:13px}#__jz_tabs{display:flex;gap:6px;margin-left:auto}.__jz_tab{padding:6px 8px;border-radius:6px;background:transparent;color:#9fb8ff;cursor:pointer}.__jz_tab.active{background:rgba(255,255,255,.06)}#__jz_body{display:flex;height:calc(100% - 44px);background:#07101a}#__jz_left{width:50%;border-right:1px solid rgba(255,255,255,.03);overflow:auto;padding:8px}#__jz_right{flex:1;overflow:auto;padding:8px}#__jz_console{height:100%;overflow:auto;background:#02040a;padding:8px;border-radius:6px;color:#cfe6ff}#__jz_console .msg{margin-bottom:6px;padding:6px;border-radius:4px;background:rgba(255,255,255,.02)}#__jz_elements pre{white-space:pre-wrap;color:#cfe6ff;background:transparent}#__jz_footer{display:flex;gap:8px;padding:8px;background:linear-gradient(180deg,#07101a,#040612);align-items:center}#__jz_close{background:#ff6b6b;padding:6px 8px;border-radius:6px;color:#081016;cursor:pointer}#__jz_toggle_highlight{background:#4cc9f0;padding:6px 8px;border-radius:6px;color:#021018;cursor:pointer}#__jz_info{color:#9fb8ff}#__jz_highlight{position:absolute;pointer-events:none;border:2px solid #2be6a0;background:rgba(43,230,160,.08);z-index:2147483646}/* responsive full-screen for tablets */#__jz_inspector.fullscreen{left:0;right:0;top:0;bottom:0;width:100%;height:100%;border-radius:0}";document.head.appendChild(d);var w=document.createElement('div');w.id='__jz_inspector';w.innerHTML='<div id="__jz_header"><b>Joinzee Inspector</b><div id="__jz_tabs"><div class="__jz_tab active" data-tab="elements">Elements</div><div class="__jz_tab" data-tab="console">Console</div><div class="__jz_tab" data-tab="network">Network</div><div class="__jz_tab" data-tab="info">Info</div></div></div><div id="__jz_body"><div id="__jz_left"><div id="__jz_elements"><p style="margin:0 0 8px 0;color:#7fa8ff">Hover over page elements to inspect. Click to select.</p><pre id="__jz_eltree">No element selected</pre></div></div><div id="__jz_right"><div id="__jz_console" style="display:block"></div><div id="__jz_network" style="display:none;padding:6px;color:#9fb8ff;" ></div><div id="__jz_info" style="display:none;padding:6px;color:#9fb8ff"></div></div></div><div id="__jz_footer"><div id="__jz_toggle_highlight">Toggle Highlight</div><div id="__jz_close">Close</div><div style="flex:1"></div><div id="__jz_dims" style="color:#9fb8ff"></div></div>';document.documentElement.appendChild(w);var h=document.createElement('div');h.id='__jz_highlight';document.body.appendChild(h);var sel=null,highlightOn=true;function fmt(e){try{return'<'+e.tagName.toLowerCase()+(e.id?" id=\""+e.id+'\"':'')+(e.className?" class=\""+e.className+'\"':'')+'>';}catch(err){return String(e);} }function updateTree(e){var out='';if(!e)return document.getElementById('__jz_eltree').textContent='No element selected';var cur=e;while(cur&&cur.nodeType===1){out=fmt(cur)+'\n'+out;cur=cur.parentElement;}document.getElementById('__jz_eltree').textContent=out;}document.addEventListener('mousemove',function(ev){if(!highlightOn)return;var t=ev.target;var r=t.getBoundingClientRect();h.style.left=(r.left+window.scrollX)+'px';h.style.top=(r.top+window.scrollY)+'px';h.style.width=r.width+'px';h.style.height=r.height+'px';},true);document.addEventListener('click',function(ev){if(ev.target.closest && ev.target.closest('#__jz_inspector'))return;ev.preventDefault();ev.stopPropagation();sel=ev.target;updateTree(sel);},true);var cdiv=document.getElementById('__jz_console');(function(){var oldLog=console.log,oldErr=console.error,oldWarn=console.warn;function pushMsg(type,args){var m=document.createElement('div');m.className='msg';m.textContent='['+type+'] '+Array.from(args).map(function(a){try{return typeof a==='object'?JSON.stringify(a):String(a);}catch(e){return String(a);} }).join(' ');cdiv.appendChild(m);cdiv.scrollTop=cdiv.scrollHeight;}console.log=function(){oldLog.apply(console,arguments);pushMsg('log',arguments)};console.error=function(){oldErr.apply(console,arguments);pushMsg('error',arguments)};console.warn=function(){oldWarn.apply(console,arguments);pushMsg('warn',arguments)};})();var net=document.getElementById('__jz_network');(function(){var origFetch=window.fetch;window.fetch=function(){var args=arguments;var t=Date.now();return origFetch.apply(this,arguments).then(function(res){var clone=res.clone();clone.text().then(function(body){var s=(Date.now()-t)+'ms '+args[0];var el=document.createElement('div');el.style.marginBottom='6px';el.style.padding='6px';el.style.borderRadius='6px';el.style.background='rgba(255,255,255,.02)';el.textContent=s;net.appendChild(el);});return res;});};var XHR=window.XMLHttpRequest;function Wrap(){var r=new XHR;var oOpen=r.open;var oSend=r.send;var start; r.open=function(method,url){r.__jz_url=url;return oOpen.apply(r,arguments)};r.send=function(){start=Date.now();this.addEventListener('load',function(){var el=document.createElement('div');el.style.marginBottom='6px';el.style.padding='6px';el.style.borderRadius='6px';el.style.background='rgba(255,255,255,.02)';el.textContent=(Date.now()-start)+'ms '+r.__jz_url;net.appendChild(el);});return oSend.apply(this,arguments)};return r}window.XMLHttpRequest=Wrap;})();function setTab(n){Array.from(document.querySelectorAll('.__jz_tab')).forEach(function(t){t.classList.toggle('active',t.dataset.tab===n)});document.getElementById('__jz_console').style.display=n==='console'?'block':'none';document.getElementById('__jz_network').style.display=n==='network'?'block':'none';document.getElementById('__jz_info').style.display=n==='info'?'block':'none';document.getElementById('__jz_elements').style.display=n==='elements'?'block':'none';}Array.from(document.querySelectorAll('.__jz_tab')).forEach(function(t){t.addEventListener('click',function(){setTab(t.dataset.tab)})});document.getElementById('__jz_toggle_highlight').addEventListener('click',function(){highlightOn=!highlightOn;document.getElementById('__jz_highlight').style.display=highlightOn?'block':'none'});document.getElementById('__jz_close').addEventListener('click',function(){w.remove();h.remove();d.remove();window.__jz_inspector_active=false});function detectTablet(){var ua=navigator.userAgent||'';var isiPad=/iPad|Macintosh/.test(ua)&&('ontouchend'in document);var sw=screen.width,sh=screen.height;var r=Math.max(sw,sh)/Math.min(sw,sh);var ipadRatio=4/3;return isiPad||Math.abs(r-ipadRatio)<0.06;}var dims=document.getElementById('__jz_dims');function updateDims(){dims.textContent=Math.round(window.innerWidth)+'x'+Math.round(window.innerHeight);}updateDims();window.addEventListener('resize',updateDims);var isTablet=detectTablet();if(isTablet){w.classList.add('fullscreen');w.style.right='0';w.style.bottom='0';w.style.left='0';w.style.top='0';}document.addEventListener('keydown',function(e){if(e.key==='Escape'){w.remove();h.remove();d.remove();window.__jz_inspector_active=false}});})();